package com.vandorlabs.neoforge.navigation.observer;
import com.vandorlabs.neoforge.transfer.*;import com.vandorlabs.machines.CoreLayout;import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.tick.LevelTickEvent;
/** Formation and dismantling share the native asynchronous durable cell journal. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeObserverTransactions {
 private static final NativeTransferSnapshot.Limits LIMITS=new NativeTransferSnapshot.Limits(4096,65536,8*1024*1024,16*1024*1024);
 private record Recipe(String design,boolean form,int facing,int x,int z,boolean inverted,int width,BlockPos target){}
 private record Pending(ServerPlayer actor,NativeObserverEntity owner,NativeCellTransactions.Request request,long weight){}
 private static final Map<ServerLevel,Map<BlockPos,Pending>> QUEUED=new IdentityHashMap<>();private static final Map<ServerLevel,Long> QUEUED_BYTES=new IdentityHashMap<>();private static long queuedBytes;
 public static void register(){NativeCellTransactions.register(FAMILY);}
 private static List<BlockPos> footprint(BlockPos root,NativeObserverDesigns.Design d,CoreLayout l,boolean inverted){var out=new ArrayList<BlockPos>();for(int y=0;y<d.height();y++)for(int x=0;x<d.width();x++)for(int z=0;z<d.depth();z++)out.add(root.offset(l.x(x,z),inverted?-y:y,l.z(x,z)));return out;}
 private static NativeRawCell capture(ServerLevel w,BlockPos p){if(!NativeObserverFormation.loaded(w,p))throw new IllegalArgumentException("Load the complete observer");var t=w.getBlockEntity(p);return new NativeRawCell(p,w.getBlockState(p),t==null?null:t.saveWithFullMetadata(w.registryAccess()),LIMITS.tileBytes());}
 public static boolean request(NativeObserverEntity owner,ServerPlayer actor,boolean form){return request(owner,actor,form,form?owner.getBlockPos():NativeObserverAccess.nearest(actor,owner));}
 public static boolean request(NativeObserverEntity owner,ServerPlayer actor,boolean form,BlockPos target){if(!NativeObserverAccess.canUse(actor,owner,target)||!owner.available()||owner.formed()==form)return false;var world=actor.serverLevel();var found=form?NativeObserverFormation.discover(owner):new NativeObserverFormation.Layout(owner.facing(),owner.layout().cornerX,owner.layout().cornerZ,owner.inverted(),owner.design().width());var d=NativeObserverDesigns.scaled(owner.design().id(),found.width());var l=new CoreLayout(d.width(),d.height(),d.depth(),found.facing().get3DDataValue(),found.x(),found.z());var before=new ArrayList<NativeRawCell>();var after=new ArrayList<NativeRawCell>();var cells=footprint(owner.getBlockPos(),d,l,found.inverted());
 for(int y=0;y<d.height();y++)for(int x=0;x<d.width();x++)for(int z=0;z<d.depth();z++){var p=owner.getBlockPos().offset(l.x(x,z),found.inverted()?-y:y,l.z(x,z));var raw=capture(world,p);before.add(raw);if(p.equals(owner.getBlockPos())){var state=raw.state.setValue(NativeObserverCoreBlock.FACING,found.facing()).setValue(NativeObserverCoreBlock.FORMED,form);var tile=new NativeObserverEntity(p,state);tile.setLevel(world);tile.loadWithComponents(raw.tile(),world.registryAccess());tile.corner(found.x(),found.z(),found.inverted(),found.width());after.add(new NativeRawCell(p,state,tile.saveWithFullMetadata(world.registryAccess()),LIMITS.tileBytes()));}else if(form){var state=NativeObserverBindings.PART.defaultBlockState();var part=new NativeObserverPartEntity(p,state);part.setLevel(world);part.owner(owner.getBlockPos());after.add(new NativeRawCell(p,state,part.saveWithFullMetadata(world.registryAccess()),LIMITS.tileBytes()));}else after.add(new NativeRawCell(p,l.frame(x,y,z)?NativeObserverFormation.matter().defaultBlockState():Blocks.AIR.defaultBlockState(),null,LIMITS.tileBytes()));}
 var encoded=new CompoundTag();encoded.putString("Design",d.id());encoded.putBoolean("Form",form);encoded.putInt("Facing",found.facing().get3DDataValue());encoded.putInt("X",found.x());encoded.putInt("Z",found.z());encoded.putBoolean("Inverted",found.inverted());if(!target.equals(owner.getBlockPos()))encoded.putLong("Target",target.asLong());if(found.width()!=com.vandorlabs.navigation.ObserverScale.baseWidth(d.id()))encoded.putInt("ObserverWidth",found.width());var request=new NativeCellTransactions.Request(owner.getBlockPos(),owner.key(),new NativeTransferSnapshot(before,LIMITS),new NativeTransferSnapshot(after,LIMITS),cells,encoded);FAMILY.readRecipe(world.registryAccess(),new NativeCellTransactions.Header(UUID.randomUUID(),FAMILY.id(),owner.getBlockPos(),owner.key(),actor.getUUID(),actor.isCreative()),request.before(),request.after(),Set.copyOf(cells),encoded);long weight=4096L+request.before().retainedBytes+request.after().retainedBytes+96L*cells.size();long inWorld=QUEUED_BYTES.getOrDefault(world,0L);if(inWorld+weight>64L*1024*1024||queuedBytes+weight>128L*1024*1024)throw new IllegalArgumentException("Wait for the pending observer construction jobs");owner.pending(true);QUEUED.computeIfAbsent(world,k->new LinkedHashMap<>()).put(owner.getBlockPos(),new Pending(actor,owner,request,weight));QUEUED_BYTES.put(world,inWorld+weight);queuedBytes+=weight;return true;
 }
 private static CompoundTag normalized(CompoundTag raw){var out=NativeObserverAliases.tile(raw).copy();for(var k:List.of("x","y","z"))out.remove(k);if(out.contains("keepPacked",1)&&!out.getBoolean("keepPacked"))out.remove("keepPacked");if(out.contains("NeoForgeData",10)&&out.getCompound("NeoForgeData").isEmpty())out.remove("NeoForgeData");return out;}
 private static final NativeCellTransactions.Family<Recipe> FAMILY=new NativeCellTransactions.Family<>(){
 public ResourceLocation id(){return ResourceLocation.parse("vandorlabs:observer_formation");}public NativeTransferSnapshot.Limits limits(){return LIMITS;}
 public Recipe readRecipe(HolderLookup.Provider regs,NativeCellTransactions.Header h,NativeTransferSnapshot before,NativeTransferSnapshot after,Set<BlockPos> held,CompoundTag tag){var keys=new HashSet<>(Set.of("Design","Form","Facing","X","Z","Inverted"));if(tag.contains("ObserverWidth"))keys.add("ObserverWidth");if(tag.contains("Target"))keys.add("Target");if(!tag.getAllKeys().equals(keys)||!tag.contains("Design",8)||!tag.contains("Facing",3)||!tag.contains("X",3)||!tag.contains("Z",3))throw new IllegalArgumentException("Observer recipe schema");for(var k:List.of("Form","Inverted"))if(!tag.contains(k,1)||tag.getByte(k)<0||tag.getByte(k)>1)throw new IllegalArgumentException("Observer flag schema");if(tag.contains("ObserverWidth")&&!tag.contains("ObserverWidth",3))throw new IllegalArgumentException("Observer width type");var d=NativeObserverDesigns.scaled(tag.getString("Design"),tag.getInt("ObserverWidth"));int f=tag.getInt("Facing"),x=tag.getInt("X"),z=tag.getInt("Z");boolean form=tag.getBoolean("Form"),inverted=tag.getBoolean("Inverted");var l=new CoreLayout(d.width(),d.height(),d.depth(),f,x,z);if(!l.canonicalCorner())throw new IllegalArgumentException("Observer corner");var expected=Set.copyOf(footprint(h.root(),d,l,inverted));if(tag.contains("Target")&&!tag.contains("Target",4))throw new IllegalArgumentException("Observer target type");var target=tag.contains("Target")?BlockPos.of(tag.getLong("Target")):h.root();if(!expected.contains(target)||form&&!target.equals(h.root()))throw new IllegalArgumentException("Observer operation target");if(!expected.equals(held)||before.cells().size()!=expected.size()||after.cells().size()!=expected.size())throw new IllegalArgumentException("Observer footprint");var old=new HashMap<BlockPos,NativeRawCell>();var next=new HashMap<BlockPos,NativeRawCell>();for(var c:before.cells())old.put(c.pos,c);for(var c:after.cells())next.put(c.pos,c);if(!old.keySet().equals(expected)||!next.keySet().equals(expected))throw new IllegalArgumentException("Observer cell set");for(int a=0;a<d.width();a++)for(int y=0;y<d.height();y++)for(int b=0;b<d.depth();b++){var p=h.root().offset(l.x(a,b),inverted?-y:y,l.z(a,b));var from=old.get(p);var to=next.get(p);if(p.equals(h.root())){if(!(from.state.getBlock() instanceof NativeObserverCoreBlock core)||!core.design.id().equals(d.id())||from.state.getValue(NativeObserverCoreBlock.FORMED)==form||!from.hasTile())throw new IllegalArgumentException("Observer core morph");var raw=from.tile();if(!raw.hasUUID("ObserverKey")||!raw.getUUID("ObserverKey").equals(h.owner()))throw new IllegalArgumentException("Observer identity");if(!form&&(from.state.getValue(NativeObserverCoreBlock.FACING).get3DDataValue()!=f||raw.getInt("ConstructorCoreX")!=x||raw.getInt("ConstructorCoreZ")!=z||raw.getBoolean("ObserverInverted")!=inverted||com.vandorlabs.navigation.ObserverScale.width(d.id(),raw.getInt("ObserverWidth"))!=d.width()))throw new IllegalArgumentException("Observer saved layout changed");if(to.state!=from.state.setValue(NativeObserverCoreBlock.FACING,Direction.from3DDataValue(f)).setValue(NativeObserverCoreBlock.FORMED,form)||!to.hasTile())throw new IllegalArgumentException("Observer core state");raw.putInt("ConstructorCoreX",x);raw.putInt("ConstructorCoreZ",z);raw.putBoolean("ObserverInverted",inverted);if(d.width()!=com.vandorlabs.navigation.ObserverScale.baseWidth(d.id()))raw.putInt("ObserverWidth",d.width());else raw.remove("ObserverWidth");if(!same(raw,to.tile()))throw new IllegalArgumentException("Observer core data changed");}else{var plain=l.frame(a,y,b)?NativeObserverFormation.matter().defaultBlockState():Blocks.AIR.defaultBlockState();var reservation=form?to:from;var original=form?from:to;if(original.state!=plain||original.hasTile()||reservation.state.getBlock()!=NativeObserverBindings.PART||!reservation.hasTile())throw new IllegalArgumentException("Observer frame morph");var raw=normalized(reservation.tile());if(!raw.contains("ConstructorOwner",4)||!BlockPos.of(raw.getLong("ConstructorOwner")).equals(h.root().subtract(p))||!raw.hasUUID("ObserverOwner")||!raw.getUUID("ObserverOwner").equals(h.owner())||raw.getAllKeys().stream().anyMatch(k->!Set.of("id","ConstructorOwner","ObserverOwner").contains(k)))throw new IllegalArgumentException("Observer reservation owner");}}return new Recipe(d.id(),form,f,x,z,inverted,d.width(),target);}
 public void authorize(ServerLevel world,NativeCellTransactions.Header h,ServerPlayer actor,Recipe r){if(!(world.getBlockEntity(h.root()) instanceof NativeObserverEntity root)||root.inert()||!root.key().equals(h.owner())||!NativeObserverAccess.journal(actor,root,r.target,h))throw new IllegalArgumentException("Observer owner/player changed");var d=NativeObserverDesigns.scaled(r.design,r.width);var l=new CoreLayout(d.width(),d.height(),d.depth(),r.facing,r.x,r.z);for(var p:footprint(h.root(),d,l,r.inverted))if(!NativeObserverFormation.loaded(world,p)||!NativeObserverAccess.unlocked(world,h,p)||!world.mayInteract(actor,p)||!actor.mayUseItemAt(p,Direction.UP,actor.getMainHandItem()))throw new IllegalArgumentException("Observer cell permission");}
 public BlockEntity stage(ServerLevel w,NativeCellTransactions.Header h,NativeRawCell c,Recipe r){return c.stage(w,t->t instanceof NativeObserverEntity||t instanceof NativeObserverPartEntity,this::same);}public boolean same(CompoundTag a,CompoundTag b){return normalized(a).equals(normalized(b));}
 public void publish(ServerLevel w,NativeCellTransactions.Header h,NativeRawCell before,NativeRawCell after,BlockEntity staged,NativeTransferHolds.Lease lease,Recipe r){if(w.getBlockState(after.pos)!=after.state)try(var scope=lease.allowOnce(after.pos)){if(!NativeObserverProtection.set(w,after.pos,after.state,Block.UPDATE_KNOWN_SHAPE))throw new IllegalStateException("Observer publication refused");}if(after.hasTile()){w.removeBlockEntity(after.pos);w.setBlockEntity(staged);staged.setChanged();}else w.removeBlockEntity(after.pos);w.getChunkAt(after.pos).setUnsaved(true);}
 public void released(ServerLevel world,NativeCellTransactions.Header h,boolean rollback,String error,Recipe r){if(world.getBlockEntity(h.root()) instanceof NativeObserverEntity root){root.pending(false);root.changed();NativeNavigationSources.add(root);}var d=NativeObserverDesigns.scaled(r.design,r.width);var l=new CoreLayout(d.width(),d.height(),d.depth(),r.facing,r.x,r.z);for(var p:footprint(h.root(),d,l,r.inverted)){if(!NativeObserverFormation.loaded(world,p))continue;world.invalidateCapabilities(p);var s=world.getBlockState(p);world.sendBlockUpdated(p,s,s,Block.UPDATE_CLIENTS);}}
 };
 @SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.LOWEST) public static void breaking(net.neoforged.neoforge.event.level.BlockEvent.BreakEvent e){if(com.vandorlabs.neoforge.gear.NativeObserverCapture.isProbe(e))return;if(e.isCanceled()||!(e.getLevel() instanceof ServerLevel w)||!(e.getPlayer() instanceof ServerPlayer actor))return;var owner=NativeObserverBindings.ownerAt(w,e.getPos());if(owner==null||!owner.formed()&&!owner.ownsRecovery())return;e.setCanceled(true);if(owner.transactionBlocked())return;try{request(owner,actor,false,e.getPos());}catch(IllegalArgumentException bad){actor.displayClientMessage(net.minecraft.network.chat.Component.literal(bad.getMessage()),true);}}
 @SubscribeEvent public static void tick(LevelTickEvent.Post e){if(!(e.getLevel() instanceof ServerLevel w))return;var pending=QUEUED.get(w);if(pending==null)return;for(var q:List.copyOf(pending.values()))try{if(NativeCellTransactions.submit(w,FAMILY,q.actor,q.request)!=null)removePending(w,q);}catch(RuntimeException bad){removePending(w,q);q.owner.pending(false);q.actor.displayClientMessage(net.minecraft.network.chat.Component.literal(bad.getMessage()==null?"Observer operation refused":bad.getMessage()),true);}if(pending.isEmpty())QUEUED.remove(w);}
 private static void removePending(ServerLevel w,Pending q){var map=QUEUED.get(w);if(map!=null&&map.remove(q.owner.getBlockPos(),q)){queuedBytes-=q.weight;long left=QUEUED_BYTES.getOrDefault(w,0L)-q.weight;if(left==0)QUEUED_BYTES.remove(w);else QUEUED_BYTES.put(w,left);}}
 @SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload e){if(e.getLevel() instanceof ServerLevel w){QUEUED.remove(w);queuedBytes-=QUEUED_BYTES.getOrDefault(w,0L);QUEUED_BYTES.remove(w);}}
 private NativeObserverTransactions(){}
}
